// BULLETPROOF: Build Groq request with conversation history
const payload = $json || {};
const message = (payload.message && typeof payload.message === 'string') ? payload.message : 'Hello';
const history = Array.isArray(payload.conversationHistory) ? payload.conversationHistory : [];
const vendor = (payload.vendor && typeof payload.vendor === 'object') ? payload.vendor : {};
const businessName = (vendor.name && typeof vendor.name === 'string') ? vendor.name : (payload.businessName || 'Our Business');

// Build system prompt (keep it simple)
const systemPrompt = `You are a friendly customer service AI for ${businessName}. Remember and reference previous messages in this conversation. Keep responses under 100 words. Be helpful and personable.`;

// Build messages array
const messages = [
  { role: 'system', content: systemPrompt }
];

// Add conversation history if present (validate each message)
if (Array.isArray(history) && history.length > 0) {
  history.forEach(h => {
    if (h && typeof h === 'object' && h.role && h.content) {
      messages.push({ role: h.role, content: h.content });
    }
  });
}

// Add current message
messages.push({ role: 'user', content: message });

// Ensure we have at least system + user message
if (messages.length < 2) {
  return { json: { error: 'Invalid message structure' } };
}

return {
  json: {
    model: 'llama-3.3-70b-versatile',
    messages: messages,
    temperature: 0.7,
    max_tokens: 500
  }
};

// BULLETPROOF: Extract reply from Groq response
const groqResponse = $json || {};

let reply = null;

// Extract from standard Groq format
if (groqResponse.choices && Array.isArray(groqResponse.choices) && groqResponse.choices.length > 0) {
  const firstChoice = groqResponse.choices[0];
  if (firstChoice && firstChoice.message && typeof firstChoice.message.content === 'string') {
    reply = firstChoice.message.content.trim();
  }
}

// Fallback
if (!reply || reply.length === 0) {
  reply = 'Sorry, I had trouble understanding. Can you rephrase that?';
}

return {
  json: {
    reply: reply
  }
};
